import{_ as o}from"./chunks/policy-new-namespace.D3fhyQI-.js";import{_ as t,o as a,c as r,a3 as n}from"./chunks/framework.Ki30n65y.js";const g=JSON.parse('{"title":"Namespace protection","description":"","frontmatter":{},"headers":[],"relativePath":"admin/namespace-protection.md","filePath":"admin/namespace-protection.md"}'),s={name:"admin/namespace-protection.md"};function c(i,e,d,l,h,p){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="namespace-protection" tabindex="-1">Namespace protection <a class="header-anchor" href="#namespace-protection" aria-label="Permalink to &quot;Namespace protection&quot;">​</a></h1><p>Namespace protection defends against <strong>dependency confusion</strong>, one of the most effective supply-chain attacks.</p><h2 id="the-attack" tabindex="-1">The attack <a class="header-anchor" href="#the-attack" aria-label="Permalink to &quot;The attack&quot;">​</a></h2><p>Your company publishes internal packages such as <code>@acme/billing</code>, <code>acme-auth</code> or <code>com.acme:core</code> to an internal registry. An attacker publishes a package with the same name on the public registry, often with a higher version number. Any build that resolves through a repository combining your internal registry and the public one may now pick up the attacker&#39;s package, and run its install scripts.</p><p>A virtual repository such as <code>all</code> asks its remotes in order and moves on when one answers &quot;not found&quot;. Without protection, a public remote can answer for an internal name, and every lookup of that name also reveals it to the public registry.</p><h2 id="how-depgate-protects-you" tabindex="-1">How DepGate protects you <a class="header-anchor" href="#how-depgate-protects-you" aria-label="Permalink to &quot;How DepGate protects you&quot;">​</a></h2><p>A <strong>Namespace protection</strong> policy lists your package names for one ecosystem. For a name in that list, DepGate:</p><ul><li><strong>asks only the remotes you trust</strong> (your internal registries by default), through every repository, including <code>all</code>;</li><li><strong>blocks</strong> the request with HTTP 403 when the requested repository has no trusted remote;</li><li><strong>answers 404</strong> when no trusted remote has the package, and never falls through to a public registry;</li><li><strong>never looks the name up</strong> on a public registry, on OSV or on deps.dev, so your internal names do not leak.</li></ul><p>When the package is found internally, your other policies (vulnerability, license and so on) evaluate it as usual.</p><p>Namespace protection is applied before everything else. A higher-priority Allow policy does not reopen public remotes, and an ordinary exception does not lift it.</p><h2 id="set-it-up" tabindex="-1">Set it up <a class="header-anchor" href="#set-it-up" aria-label="Permalink to &quot;Set it up&quot;">​</a></h2><h3 id="_1-mark-your-internal-registries" tabindex="-1">1. Mark your internal registries <a class="header-anchor" href="#_1-mark-your-internal-registries" aria-label="Permalink to &quot;1. Mark your internal registries&quot;">​</a></h3><p>In <strong>Settings → Repositories</strong>, open each remote that serves your own packages and set <strong>Source</strong> to <strong>Internal registry</strong>. Remotes are public until you say otherwise, so a reserved name is never served from an unclassified remote. See <a href="./repositories#remote-source">Repositories</a>.</p><h3 id="_2-create-the-policy-in-monitor-mode" tabindex="-1">2. Create the policy in monitor mode <a class="header-anchor" href="#_2-create-the-policy-in-monitor-mode" aria-label="Permalink to &quot;2. Create the policy in monitor mode&quot;">​</a></h3><ol><li>Choose <strong>Policies → New policy</strong>.</li><li><strong>Name</strong>: for example <code>Protect the @acme namespace</code>. <strong>Ecosystem</strong>: the single ecosystem to protect.</li><li><strong>Rule</strong>: Namespace protection. <strong>Enforcement</strong>: Monitor only.</li><li>Under <strong>Your package names</strong>, add your scopes and prefixes (see the syntax below).</li><li>Under <strong>Serve only from</strong>, keep the internal registries selected. Select a public registry only where you truly own the namespace there, such as your npm organization scope on npmjs.com.</li><li>Optionally, choose <strong>Add exceptions</strong> to list names you publish publicly on purpose, such as <code>@acme/eslint-config</code>.</li><li>Choose <strong>Test a name</strong> and try an internal name to confirm where it would be served from.</li><li>Choose <strong>Create policy</strong>.</li></ol><p><img src="'+o+'" alt="A Namespace protection policy"></p><h3 id="_3-review-the-monitoring-page" tabindex="-1">3. Review the Monitoring page <a class="header-anchor" href="#_3-review-the-monitoring-page" aria-label="Permalink to &quot;3. Review the Monitoring page&quot;">​</a></h3><p>In monitor mode nothing changes for clients. Every download of a reserved name that a <strong>public</strong> remote served is recorded on the Monitoring page. For each one, either publish the package to your internal registry, or list it under <strong>Exceptions: allow from any remote</strong>.</p><h3 id="_4-enforce" tabindex="-1">4. Enforce <a class="header-anchor" href="#_4-enforce" aria-label="Permalink to &quot;4. Enforce&quot;">​</a></h3><p>When the report is empty or every remaining entry is understood, choose <strong>Enforce</strong>.</p><h2 id="name-syntax" tabindex="-1">Name syntax <a class="header-anchor" href="#name-syntax" aria-label="Permalink to &quot;Name syntax&quot;">​</a></h2><p>Matching respects segment boundaries: <code>com.acme</code> never matches <code>com.acmecorp</code>, and a prefix must end with a separator (<code>acme-*</code>, not <code>acme*</code>).</p><table tabindex="0"><thead><tr><th>Ecosystem</th><th>Forms</th><th>Example</th></tr></thead><tbody><tr><td>npm</td><td>A whole scope, a prefix, or an exact name</td><td><code>@acme</code> matches <code>@acme/billing</code>; <code>acme-*</code> matches <code>acme-auth</code></td></tr><tr><td>PyPI</td><td>A prefix or an exact name (normalized: <code>_</code> and <code>.</code> equal <code>-</code>)</td><td><code>acme-*</code> matches <code>acme_auth</code> and <code>Acme.Auth</code></td></tr><tr><td>Go</td><td>A module path prefix</td><td><code>github.com/acme</code> matches <code>github.com/acme/svc/v2</code></td></tr><tr><td>Maven</td><td>A groupId prefix, optionally with an artifact</td><td><code>com.acme</code> matches <code>com.acme:core</code> and <code>com.acme.billing:api</code></td></tr><tr><td>NuGet</td><td>An ID prefix or an exact ID</td><td><code>Acme.*</code> matches <code>Acme.Billing</code></td></tr><tr><td>Cargo</td><td>A crate prefix or an exact name</td><td><code>acme-*</code> matches <code>acme_core</code></td></tr><tr><td>Composer</td><td>A vendor, a vendor prefix, or an exact name</td><td><code>acme/*</code> matches <code>acme/billing</code></td></tr><tr><td>RubyGems</td><td>A prefix or an exact name</td><td><code>acme-*</code> matches <code>acme_billing</code></td></tr></tbody></table><p>Patterns that would cover far too much are refused, such as <code>*</code>, a shared host on its own (<code>github.com</code>), or a one-segment Maven groupId (<code>com</code>).</p><h2 id="recommendations-for-clients" tabindex="-1">Recommendations for clients <a class="header-anchor" href="#recommendations-for-clients" aria-label="Permalink to &quot;Recommendations for clients&quot;">​</a></h2><ul><li><strong>npm</strong>: claim your scope on npmjs.com as an organization. DepGate still protects you if you lose it.</li><li><strong>Go</strong>: set <code>GONOSUMDB</code> to your internal module paths, so the <code>go</code> command does not send them to <code>sum.golang.org</code>. The policy form shows the exact value. Do not use <code>GOPRIVATE</code> for this: it also makes <code>go</code> bypass DepGate.</li><li><strong>NuGet</strong>: reserve your ID prefix on nuget.org.</li><li><strong>PyPI, Cargo, RubyGems</strong> have no namespaces. Choose distinctive prefixes.</li></ul><h2 id="collision-check-optional" tabindex="-1">Collision check (optional) <a class="header-anchor" href="#collision-check-optional" aria-label="Permalink to &quot;Collision check (optional)&quot;">​</a></h2><p>DepGate can check once a day whether your internal names also exist on the public registries, which may indicate an attack in progress. Turn on <strong>Namespace collision check</strong> under <strong>Settings → Repositories → Gateway security</strong>. Collisions are listed on the policy and sent to webhooks as <code>namespace_collision</code> events.</p><p>The check is off by default because it sends your internal names to the public registries.</p><h2 id="package-check" tabindex="-1">Package check <a class="header-anchor" href="#package-check" aria-label="Permalink to &quot;Package check&quot;">​</a></h2><p>For a reserved name, <a href="/depgate/developers/package-check">Package check</a> shows a <strong>Reserved internal namespace</strong> panel with the policy, the internal remotes that serve the name, and the public remotes that are not asked.</p>',31)])])}const y=t(s,[["render",c]]);export{g as __pageData,y as default};
